const axios = require('axios');
const cat = argumentName?.trim() || 'Any';
await sendTrackedMessage(sock, remoteJid, '😂 Fetching a joke...');
try {
  const res = await axios.get(`https://v2.jokeapi.dev/joke/${encodeURIComponent(cat)}?safe-mode&type=single`);
  if (res.data.error) {
    await sendTrackedMessage(sock, remoteJid, `❌ No jokes found for '${cat}'. Try: Programming, Pun, Misc`);
  } else {
    await sendTrackedMessage(sock, remoteJid, `😂 ${res.data.joke}`);
  }
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Failed to fetch joke.');
}
